insert into public.academy_course_structures
    (app_slug, tier, structure, content_version)
insert into public.academy_quiz_questions
    (app_slug, tier, scope, module_key, ord, prompt, options, answer_index, explanation)
values
  ('qra', 'intermediate', 'module', 'm01-potential-loss-of-life', 1, 'The JISIKE crew scenarios are stated as a process fire at 5e-4 per year with N of 1.2, a module explosion at 4e-5 per year with N of 8, a fall from height at 3e-3 per year with N of 0.5, and a spill with no one near at 6e-3 per year with N of 0. What PLL does the engine return?', '["0.006421666667", "0.002420000000", "0.009540000000", "0.000336000000"]'::jsonb, 1, 'PLL is the sum over scenarios of the frequency times the stated N, and the four products 0.000600000000, 0.000320000000, 0.001500000000 and 0.000000000000 add to 0.002420000000 fatalities per year. 0.006421666667 divides each frequency by its N where the model multiplies. 0.009540000000 adds the four frequencies and ignores N altogether. 0.000336000000 is the expected fatalities of the JISIKE off-site set, which is a different group of scenarios.'),
  ('qra', 'intermediate', 'module', 'm01-potential-loss-of-life', 2, 'Of the four JISIKE crew scenarios, which one carries the largest single contribution to the crew PLL?', '["The module explosion, at 0.000320000000 per year", "The process fire, at 0.000600000000 per year", "The fall from height, at 0.001500000000 per year", "The spill with no one near, at the largest frequency, 6e-3 per year"]'::jsonb, 2, 'The contribution of a scenario is its f times N, and the fall from height gives 3e-3 times 0.5, which is 0.001500000000 per year, the largest of the four. The module explosion has the largest N of 8 but a small frequency, so it adds only 0.000320000000. The process fire adds 0.000600000000. The spill has the largest frequency but an N of 0, so it adds nothing at all.'),
  ('qra', 'intermediate', 'module', 'm01-potential-loss-of-life', 3, 'What does the module explosion alone, stated at 4e-5 per year with an N of 8, add to the JISIKE crew PLL?', '["0.000320000000", "0.000040000000", "0.000600000000", "0.001500000000"]'::jsonb, 0, 'The module explosion contributes f times N, 4e-5 times 8, which the engine prints as 0.000320000000 per year. 0.000040000000 is the frequency alone with N ignored, the mistake that inflates the whole set to 0.009540000000. 0.000600000000 is the process fire and 0.001500000000 is the fall from height, both of them other rows of the same table.'),
  ('qra', 'intermediate', 'module', 'm01-potential-loss-of-life', 4, 'The engine''s model string for PLL says something about N beyond naming it. What does it say?', '["N must be a whole count of deaths, since a fraction of a person cannot die, and a fractional N is rounded up first.", "N is the head count present in the area of the scenario, whether or not anyone there would die in it.", "N is the probability of death at the scenario''s worst place, multiplied by one hundred people.", "N is the expected number of deaths of the scenario and is not necessarily whole, citing PB 6.3 and 6.4."]'::jsonb, 3, 'The model string reads, verbatim: "PLL = sum f_i x N_i; N the expected number of deaths of the scenario (PB 6.3, 6.4: not necessarily whole)". The engine accepts an N of 1.2 or 0.5 without rounding, because an expected value need not be a whole number. A head count is the population before any probability of death is applied to it. N is a number of deaths, so a probability dressed as N misreads the input entirely.'),
  ('qra', 'intermediate', 'module', 'm01-potential-loss-of-life', 5, 'The JISIKE spill with no one near is stated at 6e-3 per year with an N of 0. What happens to it in the PLL call?', '["It is refused, because the engine requires every scenario to carry an N above zero before it will sum anything.", "It is accepted and adds 0.000000000000 per year, since f times an N of 0 is zero whatever the frequency.", "It adds its whole frequency of 6e-3 per year, since each scenario is counted once whether anyone dies in it.", "It is dropped from the list before the sum and its frequency is reported in a separate field beside the PLL."]'::jsonb, 1, 'The course''s table prints the spill''s f times N as 0.000000000000, and the engine accepts an N of 0 because the allowed range is 0 or more. Only a negative N is refused. Counting its frequency is the N ignored mistake behind 0.009540000000. Setting zero death scenarios aside with their frequency reported is what the F-N curve does, and the PLL call simply carries the zero contribution.'),
  ('qra', 'intermediate', 'module', 'm01-potential-loss-of-life', 6, 'A PLL call is given a scenario named ''fire'' with fatalities of minus one. The engine refuses it. Which message is the engine''s own words?', '["scenarios[0].fatalities: ''fire'' must have 0 or more fatalities (an expected number need not be whole)", "scenarios[0].frequencyPerYr: ''fire'' must have a frequency of 0 or more per year", "scenarios[0].fatalityProbability: ''fire'' must be a probability of death in [0, 1]", "scenarios[0].name: every scenario needs a name"]'::jsonb, 0, 'The refusal table in the course gives this exact string for negative fatalities in potentialLossOfLife, naming the field scenarios[0].fatalities. The other three are real engine messages for other inputs: a negative frequency in locationIndividualRisk, a probability of death above one in the same function, and a nameless scenario in fnCurve. None of them is what a negative N returns.'),
  ('qra', 'intermediate', 'module', 'm01-potential-loss-of-life', 7, 'A manager reads the JISIKE crew PLL of 0.002420000000 as the chance that someone on the crew dies this year. What does the course say about that reading?', '["It is a fair reading while the figure stays below one, and it becomes a count only after it passes one.", "It is right, since PLL is the probability that at least one of the 60 people on the crew dies in the year.", "PLL is an expected number of deaths per year, never a probability, and for a large enough population it can exceed one.", "It is right once the PLL has been divided by the crew''s head count, which turns the expected value into a chance."]'::jsonb, 2, 'The course says PLL is an expected number of deaths per year, that it is never a probability, and that it can exceed one for a large enough population, so no threshold turns it into a chance. The probability that at least one person dies is a different quantity the engine never returns. Dividing by the head count gives a figure per person, which is still an expectation and still no probability.'),
  ('qra', 'intermediate', 'module', 'm01-potential-loss-of-life', 8, 'Which inputs does potentialLossOfLife take?', '["scenarios with frequencyPerYr and fatalityProbability, one per place", "pllPerYr and exposedHoursPerYr, both as plain numbers per year", "locations with lsirPerYr and occupancyFraction or hoursPerYr", "scenarios with frequencyPerYr and fatalities"]'::jsonb, 3, 'The function table in the course lists potentialLossOfLife as taking scenarios with frequencyPerYr and fatalities, and returning the PLL and each scenario contribution. Scenarios with a fatalityProbability feed locationIndividualRisk, which returns an LSIR. pllPerYr and exposedHoursPerYr feed fatalAccidentRateFromPll. Locations with an LSIR and an occupancy feed individualRiskPerAnnum.'),
  ('qra', 'intermediate', 'module', 'm01-potential-loss-of-life', 9, 'Individual risk follows one person. What question does potential loss of life answer instead?', '["How many deaths a year are expected across everyone the scenarios reach, as the expected value of societal risk.", "What individual risk the most exposed person on the crew carries, taken over every place they occupy in the year.", "What individual risk a person would carry at one place all the time, outdoors and unprotected there.", "How often an event kills fifty or more people at once, read against the one published R2P2 point."]'::jsonb, 0, 'The course opens the Professional tier by saying individual risk follows one person while societal risk asks how many die at once, and PLL is its expected value. The most exposed person over a year is an IRPA, and one place all the time is an LSIR, both of them Associate quantities. The frequency of fifty or more deaths is a point on the F-N curve, which is a different view of the same societal picture.'),
  ('qra', 'intermediate', 'module', 'm01-potential-loss-of-life', 10, 'The golden case fractional-and-zero-N carries one fractional N and one N of zero. What PLL does the engine return for it?', '["0.002420000000", "0.000685000000", "0.000336000000", "0.000600000000"]'::jsonb, 1, 'The course runs the golden case fractional-and-zero-N through the engine and prints 0.000685000000 per year. 0.002420000000 is the JISIKE crew PLL and 0.000336000000 the JISIKE off-site expected fatalities, both teaching streams with their own inputs. 0.000600000000 is the process fire contribution alone.'),
  ('qra', 'intermediate', 'module', 'm01-potential-loss-of-life', 11, 'Where does the expected number of deaths N of each scenario come from when a PLL is built?', '["The PLL call derives it from the LSIR at each place times the head count there, so the caller types only frequencies.", "It is read from the event tree, whose leaf probabilities give the share of the crew that dies in each outcome.", "It is the crew''s head count, 60, scaled down by the fraction of the year the crew is exposed on board.", "It is a stated input: the probability of death, from the consequence course, taken over the population cell by cell, and this course never computes it."]'::jsonb, 3, 'The seam table in the course says N is the probability of death over the population, cell by cell, and that this course takes it as a stated input; producing a probability of death belongs to the consequence course. The PLL call takes N as typed and derives nothing. An event tree gives outcome frequencies, and a head count scaled by exposure is still no number of deaths.'),
  ('qra', 'intermediate', 'module', 'm01-potential-loss-of-life', 12, 'Summing f over N for the JISIKE crew gives 0.006421666667. What is wrong with that figure?', '["Nothing, since it is the engine''s PLL read per death, which the vocabulary also accepts under that name.", "It leaves out the spill with no one near, whose frequency of 6e-3 per year the engine would have added in.", "It divides each frequency by its N where the model multiplies, so it is no count of deaths at all.", "It counts the fall from height twice, once for each half of its N of 0.5 that the engine keeps."]'::jsonb, 2, 'The course''s table of how PLL was built prints 0.006421666667 as the sum of f over N, derived, beside the engine''s 0.002420000000 from f times N. The model string multiplies, and nothing in the engine or its vocabulary reads a PLL per death. The spill adds nothing to f times N and cannot be divided by, so leaving it out of the wrong sum changes nothing. Nothing in either route counts a scenario twice.'),
  ('qra', 'intermediate', 'module', 'm01-potential-loss-of-life', 13, 'The vocabulary this course legislates fixes how PLL is described. Which description follows the rule?', '["The probability of a fatal accident in a year", "Expected fatalities per year, never a probability", "Fatalities per 100,000,000 exposed hours of the crew", "The yearly chance of death for the average worker on board"]'::jsonb, 1, 'The course''s vocabulary rules that PLL means expected fatalities per year and is never a probability, because it is easy to misread as one. A chance of a fatal accident or a chance of death per worker are exactly the misreadings the rule is there to stop. Fatalities per 100,000,000 exposed hours is the unit of the FAR, which is computed from a PLL and is a different quantity.'),
  ('qra', 'intermediate', 'module', 'm01-potential-loss-of-life', 14, 'When potentialLossOfLife refuses an input, what does it return?', '["An object carrying error and field, where field names the offending input", "A PLL of zero, with the reason for the refusal written into its basis block", "The PLL of the valid scenarios, with the refused one dropped from the sum", "A thrown exception carrying a stack trace and no field of its own"]'::jsonb, 0, 'The course says every function returns either a result object carrying a basis block or an object with error and field, where field names the offending input. A zero PLL would read as a real answer, and a partial sum would hide a scenario the analyst typed, so the engine returns neither. It returns the refusal as data, which is why every refusal in the table names a field.'),
  ('qra', 'intermediate', 'module', 'm01-potential-loss-of-life', 15, 'The engine''s own header lists what it declines to do. Which of these is on that list?', '["It computes N itself from each scenario''s frequency whenever the caller leaves the fatalities out.", "It refuses any scenario whose N is not a whole number, since an expected count must be an integer.", "It has no aversion weighted integral, and implements the expected value sum of f times N instead.", "It rounds every PLL to three significant figures, matching the way the Purple Book prints its figures."]'::jsonb, 2, 'The course reads from the engine''s header that it has no aversion weighted risk integral, because no source it read defines one, and that the expected value sum of f times N is implemented instead. The engine invents no number, so it never fills in an N. A fractional N is accepted, as the model string says. PLL is printed at twelve decimals, and the rounding of a published source is about that source.'),
  ('qra', 'intermediate', 'module', 'm02-the-fatal-accident-rate', 1, 'The JISIKE crew PLL is 0.002420000000 fatalities per year. The crew is 60 people, each exposed 2000 hours a year. What FAR does the engine return?', '["121.000000", "0.020167", "2.016667", "5.000000"]'::jsonb, 2, 'FAR is PLL times 100,000,000 over the exposed hours a year, and the crew''s exposed hours are 60 times 2000, 120000, which gives 2.016667. 121.000000 divides by one person''s 2000 hours instead of the crew''s. 0.020167 uses a base of 1,000,000 hours. 5.000000 is the FAR of a PLL of 2 over 4e+7 hours, a different case.'),
  ('qra', 'intermediate', 'module', 'm02-the-fatal-accident-rate', 2, 'What exposed hours a year go into the JISIKE crew FAR?', '["120000, the 60 people on the crew at 2000 hours each", "2000, the hours of any one person on the crew", "8760, one person present for the whole year on board", "4e+7, the hours of the case checked against the other course"]'::jsonb, 0, 'The course derives 120000 exposed hours a year from 60 people each exposed 2000 hours, and that is what the crew''s PLL is divided by, since the PLL counts deaths across the whole crew. 2000 is one person''s hours and gives the inflated 121.000000. 8760 is a whole year for one person and belongs to occupancy. 4e+7 is the stated hours of the whole-PLL check against the safety statistics course.'),
  ('qra', 'intermediate', 'module', 'm02-the-fatal-accident-rate', 3, 'An analyst divides the JISIKE crew PLL by the 2000 hours one person works. Which FAR do they report?', '["2.016667", "0.020167", "1.312785", "121.000000"]'::jsonb, 3, 'Dividing by one person''s hours gives 0.002420000000 times 100,000,000 over 2000, which the course shows as 121.000000, sixty times the right figure. 2.016667 is the engine''s FAR over the crew''s 120000 hours. 0.020167 is the crew figure on the wrong base of 1,000,000 hours. 1.312785 is the golden platform case, a different set of inputs.'),
  ('qra', 'intermediate', 'module', 'm02-the-fatal-accident-rate', 4, 'Which is the engine''s model string for the fatal accident rate, verbatim?', '["FAR = PLL x 1,000,000 / exposed hours per year", "FAR = PLL x 100,000,000 / exposed hours per year", "FAR = PLL x exposed hours per year / 100,000,000 hours", "FAR = IRPA x 100,000,000 / 8760 hours per year"]'::jsonb, 1, 'The course quotes the model string exactly as the key reads it. A base of 1,000,000 hours is the mistake that turns the JISIKE crew figure into 0.020167. Multiplying by the hours inverts the rate. The FAR is built from a PLL, the expected deaths of a group, and an IRPA over a year of 8760 hours is one person''s individual risk.'),
  ('qra', 'intermediate', 'module', 'm02-the-fatal-accident-rate', 5, 'A FAR is requested over zero exposed hours. Quote the refusal the engine sends back.', '["initiatingFrequencyPerYr: must be a frequency above 0 per year", "locations[0].hoursPerYr: ''deck'' must lie in [0, 8760] hours", "exposedHoursPerYr: must be above 0 hours: a rate over no exposure is undefined", "locations: the occupancy fractions sum to 1.1: one person cannot spend more than the whole year across locations"]'::jsonb, 2, 'The refusal table gives this exact string for no exposed hours, naming the field exposedHoursPerYr: a rate per hour over no hours has no value. The other three are real messages from other functions: an event tree with no initiating frequency, an occupancy of more hours than a year holds, and a roster whose fractions sum above one.'),
  ('qra', 'intermediate', 'module', 'm02-the-fatal-accident-rate', 6, 'The engine''s FAR base is imported from another engine. Which one does the basis name?', '["The hours in a year of the LOPA course''s engine, 8760, which this engine also imports and which belongs to that course", "The Purple Book section 6.3 definition of societal risk, taken from its own printed tables", "The R2P2 paragraph 136 point, read as a rate per 100,000,000 hours of exposure", "The safety statistics engine''s RATE_BASES.FAR_100M, IOGP fatalities per 100,000,000 hours"]'::jsonb, 3, 'The course quotes the basis source as engines/hse/safetyStats.js RATE_BASES.FAR_100M (IOGP: fatalities per 100,000,000 hours). The H3 hours in a year is imported too, but it converts occupancy hours for individual risk and sets no FAR base; the LOPA method itself belongs to the LOPA course. Purple Book section 6.3 defines the F-N curve, and the R2P2 point is a frequency of fifty or more deaths per year.'),
  ('qra', 'intermediate', 'module', 'm02-the-fatal-accident-rate', 7, 'A PLL of 2 over 4e+7 exposed hours is stated. What FAR does this engine return, and what does the safety statistics engine return for 2 fatalities over the same hours?', '["5.000000 here and a hundred times less there, since that course works per 1,000,000 hours", "5.000000 from each, the same number to the last bit", "12.000000 here and 5.000000 there, since this engine counts expected deaths", "2.016667 from each, since both divide by the crew''s hours"]'::jsonb, 1, 'The course shows 5.000000 from both engines on these inputs, the same number to the last bit, because the base is shared. The safety statistics course states its FAR per 100,000,000 hours as well, so no factor of a hundred separates them. 12.000000 is the golden whole-count case. 2.016667 is the JISIKE crew figure, whose PLL and hours are different.'),
  ('qra', 'intermediate', 'module', 'm02-the-fatal-accident-rate', 8, 'The same base gives the same FAR in this course and in the safety statistics course. What separates the two numbers?', '["That course counts deaths that happened; this one counts deaths expected", "That course counts hours on shore as well; this one counts hours offshore only", "That course uses a base of 1,000,000 hours; this one uses 100,000,000", "That course reports the FAR as a probability; this one reports it per year"]'::jsonb, 0, 'The course says it plainly: the safety statistics course counts deaths that happened, and this one counts deaths expected, through a PLL. The base is RATE_BASES.FAR_100M in both, per 100,000,000 hours, so a PLL of 2 over 4e+7 hours gives 5.000000 in each. Neither engine splits hours by location, and a FAR is a rate per exposed hours in both, never a probability.'),
  ('qra', 'intermediate', 'module', 'm02-the-fatal-accident-rate', 9, 'Which pair of figures does the course print for the two golden FAR cases run through the engine?', '["platform 2.016667 and whole-count 5.000000", "platform 121.000000 and whole-count 12.000000", "platform 1.312785 and whole-count 12.000000", "platform 1.312785 and whole-count 0.020167"]'::jsonb, 2, 'The course shows the golden FAR cases as platform 1.312785 and whole-count 12.000000. 2.016667 and 5.000000 are the JISIKE crew and the check against the safety statistics course. 121.000000 is the crew over one person''s hours, and 0.020167 is the crew on a base of 1,000,000 hours, both wrong builds of a teaching stream.'),
  ('qra', 'intermediate', 'module', 'm02-the-fatal-accident-rate', 10, 'How does a FAR differ from an IRPA?', '["They are one quantity in two units, since a FAR is simply an IRPA multiplied by 100,000,000 and then divided by the hours worked.", "A FAR is expected fatalities of a group per 100,000,000 exposed hours; an IRPA is one person''s individual risk per year over the places they occupy.", "A FAR is a probability of death per hour of work, while an IRPA is the count of deaths expected over a whole year across a crew.", "A FAR follows one person through a working year, while an IRPA spreads a whole crew''s expected deaths over the hours in a year."]'::jsonb, 1, 'The course builds the FAR from a PLL, expected deaths across everyone, divided by the exposed hours of that population, and builds the IRPA as the sum over places of LSIR times occupancy for one person. The two answer different questions and neither converts into the other by a unit change. A FAR is a rate and no probability, and the reading that has the FAR following one person swaps the roles of the two quantities.'),
  ('qra', 'intermediate', 'module', 'm02-the-fatal-accident-rate', 11, 'Why is 121.000000 the wrong FAR for the JISIKE crew?', '["It uses the right hours on the wrong base, 1,000,000 hours, so the figure it reports is a hundred times too large for this crew.", "It leaves out the spill with no one near, whose frequency is the largest of the four crew scenarios in the whole set.", "It treats the crew PLL as a probability, and a probability cannot be spread over the hours of a whole working year.", "The PLL counts deaths across all 60 people, so its hours must be the crew''s 120000; one person''s hours inflate the rate sixty times."]'::jsonb, 3, 'The course shows 121.000000 as the PLL over one person''s hours, beside the engine''s 2.016667 over the crew''s 120000. Dividing a group''s expected deaths by one member''s hours overstates the rate by the head count. The wrong base gives 0.020167, which is too small. The spill adds zero to the PLL either way, and nothing in the calculation reads the PLL as a probability.'),
  ('qra', 'intermediate', 'module', 'm02-the-fatal-accident-rate', 12, 'A FAR call is made directly. What must the caller pass to fatalAccidentRateFromPll?', '["pllPerYr and exposedHoursPerYr", "scenarios with frequencyPerYr and fatalities, summed inside the call", "pllPerYr and a head count of the crew, with 8760 hours per person", "individualRiskPerYr and the hours one person spends on the plant"]'::jsonb, 0, 'The function table in the course lists pllPerYr and exposedHoursPerYr, and the call returns the FAR per 100,000,000 exposed hours. The scenarios go to potentialLossOfLife first, whose PLL is then passed in. No head count is taken, since the caller supplies the exposed hours directly. An individual risk per year belongs to other functions and never feeds the FAR.'),
  ('qra', 'intermediate', 'module', 'm02-the-fatal-accident-rate', 13, 'A report quotes the JISIKE crew FAR as 2.016667 with no unit beside it. What does the course''s vocabulary require?', '["That it be stated as expected fatalities per year", "That it be converted to a probability before it is quoted", "That it be stated per 100,000,000 exposed hours", "That it be stated per person per year of exposure on board"]'::jsonb, 2, 'The course''s vocabulary rules that FAR is always per 100,000,000 exposed hours, because the same rate appears in the safety statistics course and a bare number invites a wrong base. Expected fatalities per year is the unit of the PLL. A FAR is never a probability, and a figure per person per year is the shape of an individual risk.'),
  ('qra', 'intermediate', 'module', 'm02-the-fatal-accident-rate', 14, 'The JISIKE crew FAR is 2.016667. What would the same PLL give on a base of 1,000,000 hours, and why is that wrong?', '["121.000000, since the smaller base divides by the hours of one person on the crew instead", "0.020167, a hundred times too small, since the base is fixed at 100,000,000 hours", "5.000000, since the smaller base matches the safety statistics course", "2.016667, since the base cancels out whenever the hours are the whole crew''s own"]'::jsonb, 1, 'The course shows 0.020167 for a base of 1,000,000 hours, derived, and the engine''s base is 100,000,000 hours, imported from the safety statistics engine. 121.000000 is a different mistake, one person''s hours. The safety statistics course uses the same 100,000,000 hour base, and its matching case is 5.000000 on other inputs. The base never cancels, since it multiplies the PLL directly.'),
  ('qra', 'intermediate', 'module', 'm02-the-fatal-accident-rate', 15, 'The engine''s FAR is built from a PLL. What does that make the FAR''s deaths?', '["Expected deaths, an average per year, so a FAR here need not come from any death that happened", "Recorded deaths from the incident log, averaged across the exposed hours of the crew in that year", "The deaths of the single worst scenario in the set, since a FAR is read at its largest contribution", "The deaths of scenarios with an N of one or more, since fractional N is dropped before the rate is taken"]'::jsonb, 0, 'PLL is expected fatalities per year, the sum of f times a stated N, so the FAR built on it counts deaths expected, which is how the course separates it from the safety statistics course that counts deaths that happened. The FAR takes the whole PLL, every scenario included. A fractional N such as 0.5 stays in the sum, since the engine accepts an expected number that is not whole.'),
  ('qra', 'intermediate', 'module', 'm03-the-f-n-curve', 1, 'The JISIKE off-site scenarios are stated as a toxic cloud over the town at 2e-7 per year with N of 300, a vapour cloud explosion at 1.5e-6 with N of 40, a flash fire at the road at 8e-6 with N of 12, two jet fires at the fence at 3e-5 and 1e-5 each with N of 3, and a release that reaches no one at 5e-5 with N of 0. What is F(3)?', '["0.000049700000", "0.000009700000", "0.000040000000", "0.000050000000"]'::jsonb, 0, 'F(3) is the frequency of all scenarios with 3 OR MORE deaths: both jet fires, the flash fire, the explosion and the toxic cloud, 0.000049700000 per year. 0.000009700000 is "more than 3", which drops the two jet fires sitting on the corner. 0.000040000000 counts only the scenarios with exactly 3. 0.000050000000 is the frequency of the release that reaches no one, which is kept out of the curve.'),
  ('qra', 'intermediate', 'module', 'm03-the-f-n-curve', 2, 'Continuing with those scenarios, what frequency does the curve carry at its second corner, N = 12?', '["0.000001700000", "0.000008000000", "0.000009700000", "0.000049700000"]'::jsonb, 2, 'F(12) sums every scenario with 12 or more deaths, the flash fire, the explosion and the toxic cloud, which the engine returns as 0.000009700000 per year. 0.000001700000 reads "more than 12" and loses the flash fire. 0.000008000000 is the flash fire alone, the scenarios with exactly 12. 0.000049700000 is the previous corner, F(3).'),
  ('qra', 'intermediate', 'module', 'm03-the-f-n-curve', 3, 'At the corner N = 40, which F does the JISIKE off-site step curve carry?', '["0.000000200000", "0.000001500000", "0.000009700000", "0.000001700000"]'::jsonb, 3, 'Two scenarios reach 40 deaths or more, the vapour cloud explosion and the toxic cloud over the town, and their frequencies add to 0.000001700000 per year. Dropping the explosion, as a strict reading does, leaves 0.000000200000. Keeping the explosion without the town cloud leaves 0.000001500000. The value 0.000009700000 still includes the flash fire at the road, which kills 12 and belongs to the step before.'),
  ('qra', 'intermediate', 'module', 'm03-the-f-n-curve', 4, 'An analyst reads F(12) on the JISIKE off-site set as 0.000008000000. What did they do?', '["They read \"more than 12\", which the introduction of the Purple Book prints", "They counted only the scenario with exactly 12 deaths", "They added in the release that reaches no one, at 5e-5 per year", "They divided F(12) by the 12 deaths at that corner, as a frequency per death"]'::jsonb, 1, 'The course''s table prints 0.000008000000 as the frequency of the scenarios with exactly N at the corner of 12, which is the flash fire alone. Reading "more than 12" gives 0.000001700000. Adding the release that reaches no one would raise the figure, and that scenario is kept out of the curve anyway. Dividing a corner by its N has no meaning on a curve of frequencies and gives no figure the course shows.'),
  ('qra', 'intermediate', 'module', 'm03-the-f-n-curve', 5, 'Reading the JISIKE off-site curve as a step function, what is F(5)?', '["0.000009700000 per year, the value it takes at F(12)", "0.000049700000 per year, the value it takes at F(3)", "0.000000000000 per year, since no scenario has an N of 5", "0.000040000000 per year, the jet fires carried forward"]'::jsonb, 0, 'F(5) is the frequency of 5 or more deaths, and no scenario has an N between 3 and 12, so F(5) = F(12) = 0.000009700000 per year, as the course reads the step. F(3) includes the two jet fires, whose 3 deaths are fewer than 5. A curve of N or more is never zero merely because no scenario sits at that N. The jet fires sum to 0.000040000000, and they have fewer than 5 deaths.'),
  ('qra', 'intermediate', 'module', 'm03-the-f-n-curve', 6, 'Two JISIKE jet fires share N = 3. How does the engine place them on the curve?', '["As two corners at N = 3, drawn one above the other", "As one corner carrying the larger of the two frequencies", "As one corner at N = 6, the sum of their two N values", "As one corner at N = 3 carrying both frequencies"]'::jsonb, 3, 'The course says two scenarios sharing N = 3 make ONE corner, carrying both frequencies, since the curve takes a value at each distinct N. Two corners at one N is not a step function. Taking only the larger frequency drops the 1e-5 per year of the second jet fire. Adding their N values would claim a single event killing six, which neither scenario describes.'),
  ('qra', 'intermediate', 'module', 'm03-the-f-n-curve', 7, 'What does the engine do with the release that reaches no one, stated at 5e-5 per year with N of 0?', '["It places it at a corner at N = 0 at the foot of the curve, at 0.000050000000 per year", "It refuses the call, since an F-N curve needs every N to be above zero", "It keeps it out of the curve and reports its 0.000050000000 per year separately", "It adds its frequency to every corner, since it is counted with N or more"]'::jsonb, 2, 'Scenarios with no deaths are kept out of the curve, and the engine reports their frequency, 0.000050000000 per year, beside it. The model string takes corners only at each distinct N above zero, so there is no corner at N = 0. The call is accepted, since an N of 0 is allowed. Adding it to a corner would count a release that kills nobody among scenarios with 3 or more deaths.'),
  ('qra', 'intermediate', 'module', 'm03-the-f-n-curve', 8, 'Besides the F-N points, what expected fatalities per year does fnCurve return for the JISIKE off-site set?', '["0.000049700000", "0.000336000000", "0.002420000000", "0.000050000000"]'::jsonb, 1, 'fnCurve returns the expected fatalities per year, the sum of f times N, as 0.000336000000 for the off-site set. 0.000049700000 is F(3), the top of the curve, which is a frequency of events with 3 or more deaths and no expected count. 0.002420000000 is the JISIKE crew PLL on other scenarios. 0.000050000000 is the frequency of the release that reaches no one.'),
  ('qra', 'intermediate', 'module', 'm03-the-f-n-curve', 9, 'The area under the JISIKE off-site step curve is summed step by step, as F at each corner times the width of its step. What does it equal?', '["F at the first corner, 0.000049700000, since each later step sits under it", "The sum of the four corner values, since every step is one death wide", "The frequency kept out of the curve, 0.000050000000, since it closes the area", "The expected fatalities per year, 0.000336000000, which is the off-site PLL"]'::jsonb, 3, 'The course calls it the area identity: summed step by step, the area is 0.000336000000 per year, equal to the expected fatalities per year, and for the off-site set also the off-site PLL. It is one of the self-consistency checks of the curve. The first corner is a height and no area. The steps are wider than one death, so the corners do not simply add. The release that reaches no one adds no area, since its N is 0.'),
  ('qra', 'intermediate', 'module', 'm03-the-f-n-curve', 10, 'The Purple Book''s introduction to societal risk speaks of "more than N", while its equation 6.6 and section 6.3 say "N or more". Which reading does the engine follow?', '["N or more, following the equation, and this course does the same", "More than N, following the introduction, since it comes first", "Either one, chosen by a flag the caller sets on each call", "N or more at small N and more than N above the line''s range"]'::jsonb, 0, 'The course says the source contradicts itself and that the engine follows the equation, "N or more", as does this course. The engine exposes no flag for the other reading. Switching reading with N has no basis in the source. Reading "more than N" drops the scenarios sitting exactly at each corner, which is why the choice matters.'),
  ('qra', 'intermediate', 'module', 'm03-the-f-n-curve', 11, 'What does reading "more than N" do to the JISIKE off-site curve at every corner?', '["It adds the scenarios just below the corner, so each corner rises", "It changes nothing, since no two scenarios share one value of N", "It drops the scenarios sitting exactly at that corner, so each corner falls", "It removes only the release that reaches no one from the curve"]'::jsonb, 2, 'The course''s comparison shows "more than N" below "N or more" at every corner: at 3 it reads 0.000009700000 against 0.000049700000, and at 300 it reads 0.000000000000. The corner''s own scenarios are dropped, and nothing is added. Two jet fires do share N = 3, and the release that reaches no one is outside the curve under either reading.'),
  ('qra', 'intermediate', 'module', 'm03-the-f-n-curve', 12, 'Since no published worked F-N example exists, how is the engine''s curve checked?', '["A worked F-N example printed in the Purple Book, reproduced at every corner to twelve decimals", "Self-consistency only: a brute force count at each corner, a second route on a grid of N, and the area identity", "The CCPS and HSE worked societal examples, which the engine reproduces within their rounding", "The R2P2 point, which fixes the curve at N = 50 and so pins every other corner of it"]'::jsonb, 1, 'The course says no source the engine read prints a worked F-N curve or a worked societal calculation, and the CCPS and HSE worked examples were not available. The curve is therefore checked by self-consistency only, through the three routes named in the key. The R2P2 point is a criterion the curve is compared with, which fixes nothing about the curve itself.'),
  ('qra', 'intermediate', 'module', 'm03-the-f-n-curve', 13, 'An analyst writes up the JISIKE off-site F(12) of 0.000009700000 per year. How may the write-up describe that figure?', '["As a published reproduction, since the Purple Book prints the same curve in its own worked example", "As verified against the Bevi points, since those three points lie on the curve at N of 10, 100 and 1000", "As a figure matched to the CCPS worked societal example, which the engine reproduces to the last printed digit", "As the engine''s N or more result, checked by self-consistency, with no published F-N example behind it"]'::jsonb, 3, 'The course never presents an F-N figure as a published reproduction, because no published worked F-N example exists. The Bevi points lie on the Purple Book criterion line, which is the published side, and say nothing about this curve. The CCPS and HSE worked examples were not available to the engine, so nothing was matched to them.'),
  ('qra', 'intermediate', 'module', 'm03-the-f-n-curve', 14, 'Quote the basis model the engine writes beside every F-N curve.', '["F(N) = sum of f_i with N_i >= N, at each distinct N_i > 0 (left-continuous step function)", "F(N) = sum of f_i with N_i > N, at each distinct N_i >= 0 (right-continuous step function)", "F(N) = sum of f_i x N_i over every scenario, at each distinct N_i > 0 (a cumulative sum)", "F(N) = f_i at N_i alone, at each distinct N_i > 0, joined by straight lines between corners"]'::jsonb, 0, 'The course quotes the model string in the key word for word: N or more, corners only at N above zero, a left-continuous step. The strict inequality is the "more than N" reading, and counting N of zero would put the release that reaches no one on the curve. A sum of f times N is the expected fatalities. A frequency at one N alone is the exactly N reading, and the curve holds steps with no straight lines.'),
  ('qra', 'intermediate', 'module', 'm03-the-f-n-curve', 15, 'One scenario in an F-N call carries no name. What error string comes back from fnCurve?', '["tree.branches[0].name: every branch needs a name", "scenarios: must be a non-empty list of scenarios", "scenarios[0].name: every scenario needs a name", "criterion.exponentAlpha: must be above 0 (1 is risk neutral, 2 risk averse)"]'::jsonb, 2, 'The refusal table gives this exact string for fnCurve with a nameless scenario, naming scenarios[0].name. The branch message is the event tree''s refusal for a branch with no name, and the empty list message is the one locationIndividualRisk returns when it has no scenarios. The exponentAlpha message belongs to fnCriterionComparison when a line is given no slope.'),
  ('qra', 'intermediate', 'module', 'm04-criterion-lines', 1, 'What are the constants of the engine''s one line preset, vrom-establishments?', '["C = 1e-3 and alpha = 1, from N = 1, with no upper end", "C = 0.01 and alpha = 1, from N = 1, as the R2P2 slope", "C = 1e-3 and alpha = 2, from N = 10, capped at N = 100", "C = 1e-3 and alpha = 2, from N = 10, with no upper end"]'::jsonb, 3, 'The course gives the preset as C = 1e-3, alpha = 2, from N = 10 with no upper end, citing Purple Book Figure 6.8 and Bevi article 13(1)(b). An alpha of 1 is the slope the course calls risk neutral, which the Dutch line does not use. C = 0.01 with alpha 1 is a line an analyst may supply through the R2P2 point, and it is no preset. The cap at N = 100 is a variant the course builds on purpose, and the preset has none.'),
  ('qra', 'intermediate', 'module', 'm04-criterion-lines', 2, 'On the Dutch line, what criterion frequency stands at the JISIKE corner N = 12?', '["0.000009700000", "0.000006944444", "0.000010000000", "0.000000625000"]'::jsonb, 1, 'The line is 1e-3 over 12 squared, which the course shows as 0.000006944444 per year at that corner. 0.000009700000 is the curve''s own F(12), the other side of the comparison. 0.000010000000 is the line at N = 10, where it starts. 0.000000625000 is the line at the next corner, N = 40.'),
  ('qra', 'intermediate', 'module', 'm04-criterion-lines', 3, 'Dividing the curve by the line at the first checked JISIKE corner gives which ratio?', '["1.396800", "2.720000", "0.014910", "18.000000"]'::jsonb, 0, 'The ratio is F(12) of 0.000009700000 over the line''s 0.000006944444, which the engine returns as 1.396800, so that corner EXCEEDS. 2.720000 is the ratio at N = 40 and 18.000000 the ratio at N = 300. 0.014910 is the worst ratio against a different criterion, the line of slope minus one an analyst supplies.'),
  ('qra', 'intermediate', 'module', 'm04-criterion-lines', 4, 'What state and worst ratio does the engine return for the JISIKE off-site curve against the Dutch line?', '["EXCEEDS, worst ratio 2.720000 at N = 40.000000", "BELOW, worst ratio 0.001000 at N = 50.000000", "EXCEEDS, worst ratio 18.000000 at N = 300.000000", "TOUCHES, worst ratio 1.000000 at N = 10.000000"]'::jsonb, 2, 'The course shows state EXCEEDS with a worst ratio of 18.000000 at N = 300.000000, the largest of the three checked corners. 2.720000 at N = 40 is the worst only when the line is capped at N = 100, which pulls the last check back to N = 100. BELOW at 0.001000 is the curve against the R2P2 point. TOUCHES at 1.000000 is a curve built to sit on the line at N = 10.'),
  ('qra', 'intermediate', 'module', 'm04-criterion-lines', 5, 'Why does the engine compare the curve with a criterion line only at the curve''s corners?', '["Between corners the curve is undefined, so no ratio can be taken there, and the engine skips those stretches.", "The corners are where the published Bevi points sit, so they are the only places the line is known exactly.", "Checking every N would take too long, so the engine samples the corners as a fast approximation of the result.", "F is flat on each step while the line falls with N, so the ratio on a step is largest at its right corner, which the curve attains."]'::jsonb, 3, 'The course says corners decide everything: F is flat on each step and the line falls with N, so on each step the ratio of F to the line is largest at the right corner, which the curve attains, and the comparison is exact. The curve is defined everywhere as a step. The Bevi points sit at N of 10, 100 and 1000, which are not the JISIKE corners. Nothing here is an approximation.'),
  ('qra', 'intermediate', 'module', 'm04-criterion-lines', 6, 'Why is the JISIKE corner at N = 3 left out of the comparison with the Dutch line?', '["Its ratio is below one, so the engine drops it as a corner that cannot exceed the line", "It lies below the line''s smallest N of 10, so it is outside the range the line covers", "Two scenarios share that corner, and a shared corner is compared only against a point", "Its frequency is the largest on the curve, so it is set aside as an outlier to the line"]'::jsonb, 1, 'The course says the corner at N = 3 lies below the line''s smallest N of 10 and is not checked, since the preset runs from N = 10. The engine checks every corner inside the range whatever its ratio. A shared corner is an ordinary corner. No corner is ever discarded as an outlier.'),
  ('qra', 'intermediate', 'module', 'm04-criterion-lines', 7, 'On the JISIKE step ending at N = 40, from what N does F lie above the Dutch line?', '["24.253563", "12.000000", "10.153462", "70.710678"]'::jsonb, 0, 'On that step F is 0.000001700000, and the line falls to it at N = (1e-3 / F)^(1/2) = 24.253563, derived; that is larger than the previous corner of 12 and the line''s smallest N of 10, so F lies above the line from 24.253563 to 40. 12.000000 is the previous corner, which the line is still above at this F. 10.153462 is the start of the exceeding range on the step ending at 12, and 70.710678 is the start on the step ending at 300.'),
  ('qra', 'intermediate', 'module', 'm04-criterion-lines', 8, 'The engine reports where on each exceeding step F lies above the line. Which rule sets the start of that range?', '["The previous corner of the curve alone, since the step begins there and F is flat along the whole of it", "The line''s smallest N alone, since every exceeding step is taken to begin where the criterion begins", "The largest of the previous corner, the line''s smallest N, and (C / F)^(1 / alpha), the N where the line falls to F", "The midpoint of the step, since the line crosses a flat step halfway between its two corners"]'::jsonb, 2, 'The course states the rule as the largest of the three candidates, running to the corner itself. The previous corner alone would claim the step ending at 40 exceeds from 12, where the line still lies above F. The line''s smallest N alone would start every range at 10. Nothing makes the crossing fall at a midpoint, since the line is a power law.'),
  ('qra', 'intermediate', 'module', 'm04-criterion-lines', 9, 'Between the corners at 3 and 12 deaths, at what N does the JISIKE curve first rise above the Dutch line?', '["10.000000", "3.000000", "24.253563", "10.153462"]'::jsonb, 3, 'Solving 1e-3 / N^2 = 0.000009700000 puts the crossing at 10.153462, just past the start of the line, and the curve stays above until the corner at 12. At exactly 10.000000 the criterion is 0.000010000000, a shade higher than the curve. 3.000000 lies outside the Dutch range entirely. 24.253563 belongs to the step that follows.'),
  ('qra', 'intermediate', 'module', 'm04-criterion-lines', 10, 'On the JISIKE step ending at N = 300, where does the exceeding range begin?', '["40.000000", "70.710678", "24.253563", "100.000000"]'::jsonb, 1, 'The toxic cloud alone holds this last step at 0.000000200000, and the power law meets that height at 70.710678, so the curve sits over the criterion from there to 300. At 40.000000 the criterion is 0.000000625000, well over the curve. 24.253563 is where the middle step crosses. 100.000000 is where a capped variant stops, and the preset is uncapped.'),
  ('qra', 'intermediate', 'module', 'm04-criterion-lines', 11, 'The same Dutch constants are given with an upper end at N = 100. What does the engine report at the top of the range?', '["It evaluates F at N = 100 itself, ratio 2.000000, EXCEEDS", "It stops at N = 40, the last corner inside the range, ratio 2.720000", "It evaluates the corner at N = 300 anyway, ratio 18.000000", "It refuses the line, since the curve runs past its upper end"]'::jsonb, 0, 'With the line capped at N = 100, the corner at N = 300 is out of range, and the engine evaluates F at N = 100 itself, where the curve still has a step: ratio 2.000000, EXCEEDS. The corner at 40 is still checked at 2.720000, but it does not close the range. The corner at 300 is out of range. A curve that runs past the line''s end is allowed.'),
  ('qra', 'intermediate', 'module', 'm04-criterion-lines', 12, 'What do the three Bevi values printed at N of 10, 100 and 1000 show about the Dutch line?', '["They lie above it by a factor of ten, the margin Bevi adds for new establishments", "They fix a different line with alpha 1, which the engine keeps as a second preset", "They lie on it: 1e-5, 1e-7 and 1e-9 equal C / N^alpha with the engine''s constants", "They are the points where the JISIKE off-site curve crosses the line at each N"]'::jsonb, 2, 'The course tables the printed Bevi values 1e-5, 1e-7 and 1e-9 beside C / N^alpha with the engine''s constants, and they match, which is the published side the course can cite. No factor of ten separates them. The engine has one line preset, with alpha 2. The Bevi points are criterion values, and the JISIKE curve crosses the line elsewhere, as the exceeding ranges show.'),
  ('qra', 'intermediate', 'module', 'm04-criterion-lines', 13, 'What standing does the Dutch line have in this course, given that Bevi was repealed on 1 January 2024?', '["A legal limit still in force, since the Purple Book figure outlives the repeal", "A published comparison the analyst chooses to make, the successor to Bevi unread", "A line the engine updated to the successor regulation after the repeal came in", "A line no longer offered, since the engine drops any preset with a repealed source"]'::jsonb, 1, 'The course says Bevi was repealed on 1 January 2024 and the engine did not read its successor, so the line is a published comparison the analyst chooses to make, and the engine reports a state against it. Bevi itself called the points an orientation value. The engine carries no successor values. The preset remains, with its repeal named in the source string.'),
  ('qra', 'intermediate', 'module', 'm04-criterion-lines', 14, 'An analyst supplies their own line with a slope exponent of 0. How does the comparison refuse it?', '["criterion: unknown preset ''r2p2-line''; one of vrom-establishments, r2p2-para-136, or give { constantC, exponentAlpha } or { points }", "scenarios[0].fatalities: ''fire'' must have 0 or more fatalities (an expected number need not be whole)", "scenarios[0].name: every scenario needs a name", "criterion.exponentAlpha: must be above 0 (1 is risk neutral, 2 risk averse)"]'::jsonb, 3, 'The refusal table gives this exact string for a line with no slope, naming criterion.exponentAlpha. The unknown preset message is what the same function returns for a name it does not define. The fatalities message is potentialLossOfLife refusing a negative N. The name message is fnCurve''s refusal of a nameless scenario.'),
  ('qra', 'intermediate', 'module', 'm04-criterion-lines', 15, 'Against the Dutch line, how many of the JISIKE off-site corners inside the line''s range exceed it?', '["All three, at N of 12, 40 and 300", "Two, at N of 40 and 300, since the corner at 12 sits under the line", "One, at N = 300, the corner with the worst ratio of the whole curve", "All four, since the corner at N = 3 exceeds by the largest ratio"]'::jsonb, 0, 'The course''s corner table marks EXCEEDS at 12 with ratio 1.396800, at 40 with 2.720000 and at 300 with 18.000000. The corner at 12 is above the line, since its ratio exceeds one. The worst ratio names one corner, which is not the count. The corner at N = 3 lies below the line''s smallest N and is never checked.'),
  ('qra', 'intermediate', 'module', 'm05-one-published-point-and-the-boundary', 1, 'What is the engine''s preset r2p2-para-136?', '["A line through N = 50 at 0.000200000000 per year, slope minus one", "A line with C = 1e-3 and alpha = 2, capped at N = 50", "One point, N = 50 at 0.000200000000 per year, with no slope", "Two points, N = 50 and N = 100, with a slope taken between them"]'::jsonb, 2, 'R2P2 paragraph 136 gives a single point, an accident killing 50 or more at more than one in five thousand a year, and the preset is that one point, N = 50 at 0.000200000000 per year, with no slope. The slope minus one line is common practice and no preset. C = 1e-3 with alpha 2 is the Dutch line. R2P2 prints no second point.'),
  ('qra', 'intermediate', 'module', 'm05-one-published-point-and-the-boundary', 2, 'Why does the engine give the R2P2 point no slope?', '["R2P2 defers extrapolation to other N to a reference the engine did not read", "R2P2 prints a slope of zero, so the criterion is flat at every value of N", "A slope would double count the aversion already inside the R2P2 frequency", "The engine infers the slope from the Dutch line and so needs none of its own"]'::jsonb, 0, 'The course says R2P2 defers extrapolation to other N to a reference the engine did not read, so the engine gives the point NO SLOPE and compares the curve at N = 50 only. R2P2 prints no slope at all, flat or otherwise. The engine has no aversion weighting of its own; aversion enters only through the slope of a line a caller or preset gives. It borrows nothing from the Dutch line, which is a separate preset from another source.'),
  ('qra', 'intermediate', 'module', 'm05-one-published-point-and-the-boundary', 3, 'Set against the R2P2 point, how does the JISIKE off-site curve come out?', '["EXCEEDS, ratio 18.000000 at N = 300.000000", "TOUCHES, ratio 1.000000 at N = 50.000000", "BELOW, ratio 0.014910 at N = 3.000000", "BELOW, ratio 0.001000 at N = 50.000000"]'::jsonb, 3, 'F(50) is 0.000000200000 per year against the point''s 0.000200000000, a ratio of 0.001000, and the state is BELOW. EXCEEDS at 18.000000 is the same curve against the Dutch line. TOUCHES at 1.000000 is the golden r2p2-touch case, whose curve is built to sit on the point. BELOW at 0.014910 is the curve against the line of slope minus one an analyst supplies.'),
  ('qra', 'intermediate', 'module', 'm05-one-published-point-and-the-boundary', 4, 'R2P2 paragraph 136 speaks of 50 or more deaths. How often a year does the JISIKE off-site set reach that?', '["0.000001700000, from the explosion and the toxic cloud", "0.000000200000, from the toxic cloud at N = 300 alone", "0.000000000000, since no scenario has exactly 50 deaths", "0.000001500000, from the explosion at 40, the corner below"]'::jsonb, 1, 'F(50) is the frequency of 50 OR MORE deaths, and only the toxic cloud at N = 300 has that many, so it is 0.000000200000 per year. 0.000001700000 is F(40), which includes the explosion with 40 deaths, fewer than 50. Zero is the exactly N reading, which N or more never takes. The explosion alone is 0.000001500000 and has too few deaths to count at 50.'),
  ('qra', 'intermediate', 'module', 'm05-one-published-point-and-the-boundary', 5, 'An analyst wants the common line of slope minus one through the R2P2 point. How is it given to the engine?', '["As their own criterion, C = 0.01 and alpha = 1, from N = 1 by default", "As the preset r2p2-para-136 with a flag that switches the slope on for them", "As the preset vrom-establishments with C changed to 0.01 by the engine", "As the preset r2p2-line, which the engine keeps beside the published point"]'::jsonb, 0, 'The course says the slope minus one line is common practice but is not in R2P2 and is not a preset, so the analyst gives it as their own criterion, C = 0.01 and alpha = 1, from N = 1 by default. The R2P2 preset has no slope flag. The Dutch preset has fixed constants. The name r2p2-line is refused as an unknown preset.'),
  ('qra', 'intermediate', 'module', 'm05-one-published-point-and-the-boundary', 6, 'An analyst supplies C = 0.01 and alpha = 1. Where is the worst corner of the JISIKE curve against that line, and what is the state?', '["BELOW, worst ratio 0.001000 at N = 50.000000", "EXCEEDS, worst ratio 1.396800 at N = 12.000000", "BELOW, worst ratio 0.014910 at N = 3.000000", "BELOW, worst ratio 0.014910 at N = 300.000000"]'::jsonb, 2, 'The course shows BELOW with a worst ratio of 0.014910 at N = 3.000000 against that line, which runs from N = 1 and so checks the corner at 3 as well. 0.001000 at N = 50 is the published point. 1.396800 at N = 12 is the first exceeding corner against the Dutch line. The worst ratio sits at N = 3, where F is largest against the line, and the corner at 300 is not it.'),
  ('qra', 'intermediate', 'module', 'm05-one-published-point-and-the-boundary', 7, 'When an analyst supplies their own line, what source does the engine''s basis name?', '["UK HSE, Reducing risks, protecting people (2001) para 136", "TNO Purple Book CPR 18E (1999) Figure 6.8", "the analyst''s line, as extrapolated from R2P2 paragraph 136", "criterion as given"]'::jsonb, 3, 'The course says the basis then names the source as "criterion as given", so the result shows the line is the analyst''s own. The R2P2 paragraph is the source of the preset point, and the Purple Book figure is a source of the Dutch line. The engine never claims to extrapolate R2P2, which is exactly why the line must be supplied.'),
  ('qra', 'intermediate', 'module', 'm05-one-published-point-and-the-boundary', 8, 'A curve is built from a touching scenario at 1e-5 per year with N = 10 and a small scenario at 2e-5 per year with N = 1. What does the engine return against the Dutch line?', '["EXCEEDS, since a corner equal to the line is taken as above it", "TOUCHES, with the corner at N = 10 AT_LINE at ratio 1.000000", "BELOW, since the corner at N = 1 is below the line''s range", "AT_LINE overall, with the corner at N = 10 marked as TOUCHES"]'::jsonb, 1, 'At N = 10 F is 0.000010000000 and so is the line, a ratio of 1.000000, and that corner is AT_LINE; with no corner above, the curve TOUCHES. EXCEEDS means strictly above at some corner. The corner at N = 1 is outside the range and is not checked, so BELOW misses the corner that is on the line. AT_LINE is the word for one corner and TOUCHES the word for the curve, so the reading that swaps them has the roles reversed.'),
  ('qra', 'intermediate', 'module', 'm05-one-published-point-and-the-boundary', 9, 'What does EXCEEDS mean in the engine''s state words?', '["At least one checked corner lies strictly above the line or point", "Every checked corner lies above the line, with none on or below it", "The worst ratio is at least one, counting a corner on the line too", "The expected fatalities per year exceed the line''s value at N = 1"]'::jsonb, 0, 'The course defines EXCEEDS as at least one corner strictly above. A single corner is enough, so every corner above is not needed. A corner on the line within the snap is AT_LINE and leaves the curve at TOUCHES, so a ratio of exactly one does not count. The state compares frequencies at corners and never uses the expected fatalities.'),
  ('qra', 'intermediate', 'module', 'm05-one-published-point-and-the-boundary', 10, 'The golden case r2p2-touch has F(50) = 1.5e-4 + 5e-5, which is 0.00019999999999999998 in double. What does the engine return, and why?', '["BELOW, because the sum in double falls a hair under the point''s frequency", "EXCEEDS, because the engine rounds every sum up before it compares it", "A refusal, because the frequencies at the corner do not sum to one", "TOUCHES, because a corner within 1e-9 relative of the point counts as on it"]'::jsonb, 3, 'The course shows ratio 0.9999999999999999 and state TOUCHES: within 1e-9 relative of the criterion counts as on it. Without the snap a plain comparison would call the curve BELOW, although on paper it sits exactly on the point. The engine rounds nothing up. Scenario frequencies are rates per year and are never required to sum to one.'),
  ('qra', 'intermediate', 'module', 'm05-one-published-point-and-the-boundary', 11, 'fnCriterionComparison is given the criterion ''r2p2-line''. Which message does the engine return, in its own words?', '["criterion.exponentAlpha: must be above 0 (1 is risk neutral, 2 risk averse)", "tree.branches[1].name: ''fire'' appears twice in one branch set", "criterion: unknown preset ''r2p2-line''; one of vrom-establishments, r2p2-para-136, or give { constantC, exponentAlpha } or { points }", "substance: must be one of k1-liquid, gas-low-reactivity, gas-average-high-reactivity (PB Table 4.7 classifies reactivity)"]'::jsonb, 2, 'The refusal table gives this exact string, naming the field criterion and listing the two presets the engine has. The exponentAlpha message is the same function refusing a line with no slope. The branch message is the event tree refusing one name twice in a branch set. The substance message is the direct ignition lookup refusing a class its table does not have.'),
  ('qra', 'intermediate', 'module', 'm05-one-published-point-and-the-boundary', 12, 'The criterion ''valueOf'' is passed to fnCriterionComparison. Every JavaScript object carries that name. What happens?', '["It is accepted and treated as the Dutch line, since the first preset is used whenever the name is unrecognised", "It is refused like any other unknown preset, since the engine looks a preset up only among the names it defines", "It is accepted and returns BELOW with no checks, since an inherited name carries no constants to compare", "It raises an exception inside the engine, since an inherited name cannot be looked up at all by any function"]'::jsonb, 1, 'The course says a preset name is looked up only among the names the engine itself defines, and the refusal table shows ''valueOf'' refused with the engine''s own words: criterion: unknown preset ''valueOf''. No fallback preset is ever substituted. A result with no checks would read as a real comparison. The engine returns an error and a field, which is data, and throws nothing.'),
  ('qra', 'intermediate', 'module', 'm05-one-published-point-and-the-boundary', 13, 'How wide is the snap that decides whether a corner is on the line?', '["1e-9 relative to the criterion", "1e-9 per year, taken absolute", "1e-6 relative to the criterion", "One per cent of the line value"]'::jsonb, 0, 'The course says a corner within 1e-9 relative of the line is AT_LINE, the same width as BOUNDARY_SNAP. An absolute 1e-9 per year would swallow the whole of a line near 1e-9 at N = 1000. 1e-6 would call corners on the line that are measurably off it. One per cent is no figure the engine uses.'),
  ('qra', 'intermediate', 'module', 'm05-one-published-point-and-the-boundary', 14, 'A comparison comes back BELOW. Which condition held at the checks the engine made?', '["Most checked corners lie below the criterion, with at most one of them above", "The corner with the largest N lies below the line or point", "The curve lies below the line at N = 1, where the line is at its very highest", "No corner in range reached the criterion; each sat strictly under it"]'::jsonb, 3, 'The course defines BELOW as every checked corner strictly below the line or point. One corner above makes the curve EXCEED, and one on the line makes it TOUCH. The corner with the largest N is only one of the checks. N = 1 lies outside the Dutch line''s range, and the state reads every corner in range.'),
  ('qra', 'intermediate', 'module', 'm05-one-published-point-and-the-boundary', 15, 'Which pair of words does the engine use for a corner on the line and for a curve with no exceedance and at least one such corner?', '["TOUCHES for the corner and AT_LINE for the curve", "ON_LINE for the corner and BELOW for the curve", "AT_LINE for the corner and TOUCHES for the curve", "AT_LINE for the corner and EXCEEDS for the curve"]'::jsonb, 2, 'The course''s state words table gives AT_LINE as the state of one corner on the line and TOUCHES as the overall state when no corner is above and at least one is on the line. Swapping them misreads the table. ON_LINE is no state word. A curve with no corner above cannot EXCEED, since EXCEEDS needs a corner strictly above.'),
  ('qra', 'intermediate', 'module', 'm06-societal-risk-end-to-end', 1, 'How does the Purple Book count the fraction of a population cell that dies, Fd, for societal risk?', '["Fd = FE,in x FE,out, the chance of dying indoors times the chance of dying outdoors, for everyone in the cell", "Fd = FE,in x fpop,in + FE,out x (1 - fpop,in), weighting the indoor and outdoor fractions by who is indoors", "Fd = the larger of FE,in and FE,out, since each person in the cell is counted at the worse of the two places", "Fd = FE,out alone, since a person outdoors and unprotected is the case every societal count is built on"]'::jsonb, 1, 'The course gives Fd = FE,in x fpop,in + FE,out x (1 - fpop,in), where fpop,in is the fraction of the population indoors, so each fraction dying is weighted by the share of people it applies to. A product of the two fractions has no meaning for one population. Taking the worse of the two overcounts the people indoors. Outdoors and unprotected is the LSIR convention, which the societal count deliberately refines.'),
  ('qra', 'intermediate', 'module', 'm06-societal-risk-end-to-end', 2, 'What are the Purple Book fractions of deaths indoors and outdoors for?', '["Individual risk: they are the vulnerability factor applied at each place of one person''s IRPA", "Both, since the same fraction scales an LSIR and a head count by exactly the same amount", "Neither on their own: they only adjust the frequency of each outcome of the event tree above", "Societal risk: the expected deaths in a population cell are Fd times the people in it"]'::jsonb, 3, 'The course says the fractions are for SOCIETAL risk, so the expected number of deaths in a cell is Fd times the people in it, and that they are not a vulnerability factor for individual risk. The vulnerability factor of an IRPA is the analyst''s own, with a default of 1. An event tree outcome frequency is untouched by where people shelter.'),
  ('qra', 'intermediate', 'module', 'm06-societal-risk-end-to-end', 3, 'Why does this course teach the Fd rules and never grade a number that passes through them?', '["The factors and the day and night fractions are single transcriptions with no printed numeric example to test them against", "The engine computes them from a probit of its own, and the probit belongs to the consequence course, so no figure is stable", "The Purple Book withdrew the indoor fractions, so the engine carries them only for comparison with older studies", "The fractions change with each weather class, so no single value is ever returned for a given effect and period"]'::jsonb, 0, 'The course says the factors 0.1 for toxic indoors, 0.14 for fire outdoors, 0.025 for explosion indoors and the Table 5.3 fractions are single transcriptions of the Purple Book, which prints no numeric example for them, so the course teaches the rules and grades nothing through them. A probit belongs to the consequence course, and this function takes the probability of death as a stated input. Nothing says the Purple Book withdrew anything, and the period is day or night, with no weather class.'),
  ('qra', 'intermediate', 'module', 'm06-societal-risk-end-to-end', 4, 'What does the course record about the engine''s own validation of the Fd factors?', '["Every factor was matched against a second edition of the same source at twelve decimals", "The oracle found one transcription error in the explosion rules and flagged the suite red", "A wrong clothing factor planted in both the engine and its oracle left the suite green", "The factors were checked against a worked Fd example the Purple Book prints for every effect"]'::jsonb, 2, 'The course says the engine''s own validation planted a wrong clothing factor in both the engine and its oracle, and the suite stayed green, which is why no number through the fractions is graded. There is no second reading of the source behind them. No error was found and flagged, because a planted error in both places cannot be seen. The Purple Book prints no numeric example for these factors, so there was nothing to check them against.'),
  ('qra', 'intermediate', 'module', 'm06-societal-risk-end-to-end', 5, 'For an explosion, which rule does the engine apply at exactly 30000 Pa gauge?', '["The upper rule, in which everyone dies indoors and outdoors alike, since the threshold is reached", "The lower rule, in which only a fraction of those indoors die and no one outdoors", "Neither rule, since exactly 30000 Pa is refused as a value that sits on a printed edge", "The rule for 10000 Pa or less, in which nobody indoors or outdoors dies at all"]'::jsonb, 1, 'The explosion rows follow Figure 5.5: above 30000 Pa gauge everyone dies, above 10000 Pa only those indoors die in part, and exactly 30000 Pa falls in the lower rule. Everyone dies only strictly above 30000 Pa. A value on a printed edge is accepted and placed, never refused. The rule with no deaths applies only at or below 10000 Pa.'),
  ('qra', 'intermediate', 'module', 'm06-societal-risk-end-to-end', 6, 'A fire exposes a cell at 35000 W/m2 or more. What does the Purple Book rule, as the engine applies it, say?', '["Only those outdoors die, since a building shields everyone inside it", "Everyone outdoors dies and a tenth of those indoors, as for a toxic cloud", "The cell is refused, since fluxes over the ignition value are unsupported", "Everyone dies, indoors or out, as Figure 5.4 prints for Q >= 35 kW/m2"]'::jsonb, 3, 'The course says a fire at 35000 W/m2 or more kills everyone indoors or out, following Figure 5.4. Below that flux the probability of death comes from a heat probit, which is consequence modelling and belongs to the consequence course. At or above it the rule gives no shelter indoors, so neither the outdoor-only reading nor the toxic cloud''s tenth indoors applies, and the engine accepts the flux without refusing it.'),
  ('qra', 'intermediate', 'module', 'm06-societal-risk-end-to-end', 7, 'For a toxic cloud with a stated probability of death PE outdoors, how does the rule treat the people indoors?', '["The same fraction dies as outdoors, since the cloud enters every building in the cell", "None of them dies at all, since a building keeps the whole of the cloud outside", "A smaller fraction of them dies than outdoors, since the rule credits shelter indoors", "A larger fraction dies than outdoors, since the cloud collects inside the buildings"]'::jsonb, 2, 'The engine''s rule for a toxic cloud is FE,in = 0.1 PE and FE,out = PE, with PE a stated input from the consequence course, so those indoors carry a smaller fraction. Equal fractions would credit buildings with nothing. Zero indoors would claim a perfect seal, which the rule never does. A larger fraction indoors reverses the rule. The factor itself is a single transcription, so the course teaches its direction and grades no figure through it.'),
  ('qra', 'intermediate', 'module', 'm06-societal-risk-end-to-end', 8, 'A societal call asks pbFatalityFractions for the fractions at ''dusk''. What refusal comes back, word for word?', '["period: must be ''day'' or ''night'' (PB Table 5.3), or give fractionIndoors", "effect: must be ''toxic'', ''fire'', ''flash-fire'' or ''explosion''", "exposedHoursPerYr: must be above 0 hours: a rate over no exposure is undefined", "locations[0].vulnerabilityFactor: ''deck'' must be a factor in [0, 1]"]'::jsonb, 0, 'The refusal table gives this exact string for a period the table does not have, naming the field period. The effect message is the same function refusing an effect it does not have. The exposed hours message belongs to the FAR. The vulnerability factor message belongs to the IRPA, whose factor is the analyst''s own and separate from these fractions.'),
  ('qra', 'intermediate', 'module', 'm06-societal-risk-end-to-end', 9, 'What does the engine do with a flash fire at night?', '["Those indoors are spared inside the envelope, since the walls stop the flame front", "Only the fraction of people indoors at night dies inside the envelope", "It weights the envelope by the night fraction indoors before any count", "Everyone inside the envelope dies and no one outside it does, indoors or out"]'::jsonb, 3, 'The course runs a flash fire inside the envelope at night to an Fd of everyone and outside it to none, with the same fraction indoors and outdoors in each case. Buildings give no shelter from a flash fire inside the envelope in this rule. The night fraction indoors still enters Fd, but with equal fractions in and out it changes nothing.'),
  ('qra', 'intermediate', 'module', 'm06-societal-risk-end-to-end', 10, 'For the JISIKE off-site set, which pair belongs together in one societal picture?', '["Expected fatalities 0.002420000000 per year and a curve that TOUCHES the Dutch line at the single corner of 10 deaths", "Expected fatalities 0.000049700000 per year and a curve that EXCEEDS both the Dutch line and the published R2P2 point", "Expected fatalities 0.000336000000 per year and a curve that EXCEEDS the Dutch line yet sits BELOW the R2P2 point", "Expected fatalities 0.000050000000 per year and a curve that stays BELOW every criterion the engine carries"]'::jsonb, 2, 'The off-site set gives expected fatalities of 0.000336000000 per year, EXCEEDS against the Dutch line with a worst ratio of 18.000000, and BELOW against the R2P2 point at 0.001000. 0.002420000000 is the crew PLL, and the touching curve is a separate built case. 0.000049700000 is F(3), a frequency. 0.000050000000 is the frequency kept out of the curve.'),
  ('qra', 'intermediate', 'module', 'm06-societal-risk-end-to-end', 11, 'Which order builds a societal picture in this course?', '["Compute N from each scenario''s Pd and head count, sum f over N for the PLL, then read the FAR off the F-N curve at N = 1", "Take each scenario''s frequency and stated N, sum f times N for the PLL, divide by exposed hours for the FAR, and build F(N) as N or more to compare at the corners", "Build F(N) as more than N, compare it with the line at every N on a grid, and then sum the corner values for the PLL", "Sum the frequencies for the PLL, band each scenario against the line, and divide by 8760 hours to get the FAR"]'::jsonb, 1, 'The Professional tier runs from stated inputs: N comes from the consequence course, PLL is the sum of f times N, FAR is PLL times 100,000,000 over the exposed hours, and the curve is N or more, compared at its corners. Computing N is the consequence course''s work, and f over N is a wrong build. "More than N" drops corner scenarios, and a grid is unnecessary since corners decide. Summing frequencies ignores N, and 8760 is one person''s year.'),
  ('qra', 'intermediate', 'module', 'm06-societal-risk-end-to-end', 12, 'The JISIKE crew and the JISIKE off-site sets are both run. Which figures, PLL in fatalities per year and FAR per 100,000,000 exposed hours, belong to the crew?', '["A PLL of 0.002420000000 and a FAR of 2.016667", "A PLL of 0.000336000000 and a FAR of 121.000000", "A PLL of 0.002420000000 and a worst ratio of 18.000000", "A PLL of 0.009540000000 and a FAR of only 0.020167"]'::jsonb, 0, 'The crew set gives a PLL of 0.002420000000 and, over 120000 exposed hours, a FAR of 2.016667. 0.000336000000 is the off-site expected fatalities, and 121.000000 is the crew over one person''s hours. The ratio of 18.000000 belongs to the off-site curve against the Dutch line. 0.009540000000 ignores N, and 0.020167 uses the wrong base.'),
  ('qra', 'intermediate', 'module', 'm06-societal-risk-end-to-end', 13, 'Which part of a societal risk assessment can be cited as published and reproduced?', '["The F-N curve of the JISIKE off-site set, reproduced from the Purple Book''s own worked example", "The Fd fractions, reproduced at every tabled case against the Purple Book''s own printed figures", "The PLL of the JISIKE crew, taken from an HSE worked example and matched to the last bit", "The criterion side: the Bevi points lie on the Purple Book line, and the R2P2 point is printed"]'::jsonb, 3, 'The course says what IS published and reproduced is the criterion side, the three Bevi points on the Purple Book line and the printed R2P2 point. No published worked F-N curve exists, so the curve is checked by self-consistency. The Purple Book prints no numeric example of the Fd fractions. The JISIKE streams are teaching inputs, and no HSE worked example was available.'),
  ('qra', 'intermediate', 'module', 'm06-societal-risk-end-to-end', 14, 'The JISIKE off-site set has a PLL of 0.000336000000 per year. Why does a societal picture carry the F-N curve as well?', '["The PLL counts only the crew on board, so the people beyond the fence need a separate curve of their own to be seen", "The PLL leaves out every scenario whose N is not whole, and the curve puts those fractional scenarios back into view", "The PLL is one expected value, and the curve shows how that total is spread between frequent small events and rare large ones", "The PLL is a probability, and the curve converts it into a frequency per year that a criterion line can be read against"]'::jsonb, 2, 'The area under the step curve equals the expected fatalities, 0.000336000000 per year for this set, so the curve carries the same total and also shows at which N it sits, which is what a criterion line is compared with at the corners. The off-site PLL already counts the people beyond the fence. A fractional N stays in the PLL. PLL is expected fatalities per year and never a probability.'),
  ('qra', 'intermediate', 'module', 'm06-societal-risk-end-to-end', 15, 'An Fd call names an effect outside the four the engine knows. What does it say back?', '["substance: must be one of k1-liquid, gas-low-reactivity, gas-average-high-reactivity (PB Table 4.7 classifies reactivity)", "effect: must be ''toxic'', ''fire'', ''flash-fire'' or ''explosion''", "criterion: unknown preset ''valueOf''; one of vrom-establishments, r2p2-para-136, or give { constantC, exponentAlpha } or { points }", "releaseType: must be ''continuous'' or ''instantaneous''"]'::jsonb, 1, 'The refusal table gives this exact string for an effect the engine does not have, naming the field effect and listing the four it does. The substance and release type messages are the direct ignition lookup refusing inputs of its own. The criterion message is fnCriterionComparison refusing a name every object inherits.'),
  ('qra', 'intermediate', 'final', null, 1, 'One JISIKE crew term in the PLL table reads 0.000600000000 fatalities per year. Which scenario is it?', '["The module explosion, at 4e-5 per year with an expected 8 deaths", "The fall from height, at 3e-3 per year with an expected 0.5 deaths", "The process fire, at 5e-4 per year with an expected 1.2 deaths", "The spill with no one near, at 6e-3 per year with no deaths expected"]'::jsonb, 2, 'Multiplying 5e-4 by 1.2 gives the 0.000600000000 the table prints for the process fire. The module explosion''s product is 0.000320000000, which is smaller despite its 8 deaths because its frequency is low. The fall from height gives 0.001500000000, the largest term. The spill gives 0.000000000000, since nobody is near it.'),
  ('qra', 'intermediate', 'final', null, 2, 'An analyst adds up the four JISIKE crew frequencies and forgets the deaths. What figure comes out?', '["0.009540000000", "0.006421666667", "0.002420000000", "0.000685000000"]'::jsonb, 0, 'Summing 5e-4, 4e-5, 3e-3 and 6e-3 with N ignored gives 0.009540000000, which the course shows as a wrong build: it counts a spill that kills nobody as heavily as a fall. 0.006421666667 is a different wrong build, f over N. 0.002420000000 is the engine''s f times N. 0.000685000000 is the golden fractional-and-zero-N case.'),
  ('qra', 'intermediate', 'final', null, 3, 'Which of these scenarios would potentialLossOfLife accept as typed?', '["One with minus 0.5 deaths, read as half a death averted by a measure", "Only one whose deaths are a whole count, since people can die only in whole numbers", "Any at all, since the engine sums whatever deaths it is given unchecked", "One with an expected 0.5 deaths, since an expected number need not be whole"]'::jsonb, 3, 'The allowed range for N is 0 or more, and the model string says an expected number need not be whole, which is why the fall from height carries 0.5. A negative N is refused in the engine''s own words, whatever it is meant to represent. Whole counts are not required. The engine does check N, which is how a negative one gets refused.'),
  ('qra', 'intermediate', 'final', null, 4, 'Besides the PLL itself, what does potentialLossOfLife hand back?', '["The F-N points and the frequency of no deaths", "Each scenario''s own contribution, its f times N", "The FAR per 100,000,000 exposed hours of the crew", "The LSIR at each place the scenarios reach"]'::jsonb, 1, 'The function table says potentialLossOfLife returns the PLL and each scenario contribution, which is how the JISIKE table shows 0.000600000000 for the process fire. The F-N points and the zero-death frequency come from fnCurve. The FAR needs exposed hours and a separate call. An LSIR needs probabilities of death at a place, which this call never takes.'),
  ('qra', 'intermediate', 'final', null, 5, 'The engine invents no number. Which default does it therefore apply when a PLL scenario leaves something out?', '["An N of one death for any scenario typed with no fatalities", "A frequency of 1e-4 per year for any scenario typed without one", "None: every frequency and every N is an input with no default", "Exposed hours of 8760 for each person when none are given"]'::jsonb, 2, 'The course reads from the engine''s header that it invents no number: every scenario frequency, probability of death, occupancy and the rest is an input. An assumed N, an assumed frequency or an assumed year of exposure would each be a number the engine made up, and it makes none. Exposed hours belong to the FAR call anyway.'),
  ('qra', 'intermediate', 'final', null, 6, 'What is the expected fatalities figure of 0.000336000000 per year for the JISIKE off-site scenarios, in PLL terms?', '["Its PLL: the same sum of frequency times deaths, taken beyond the fence", "A frequency: how often an event beyond the fence kills 3 or more people at once", "A probability: the chance that someone beyond the fence dies this year", "A rate: deaths per 100,000,000 hours spent beyond the fence by the whole town"]'::jsonb, 0, 'The expected fatalities per year the F-N call returns is the sum of f times N, and the course says that for the off-site set it is also the off-site PLL. The frequency of 3 or more deaths is F(3), 0.000049700000. PLL is never a probability. A rate per 100,000,000 hours is a FAR, which would need exposed hours this set does not state.'),
  ('qra', 'intermediate', 'final', null, 7, 'The JISIKE crew FAR is 2.016667 per 100,000,000 exposed hours. What does that figure say in words?', '["About 2.016667 people on the crew are expected to die in each and every year of operation", "About 2.016667 crew deaths are expected for every 100,000,000 hours the crew is exposed", "Each person on the crew carries a 2.016667 chance of death per 100,000,000 years", "About 2.016667 crew deaths are expected for every 100,000,000 hours worked by one person alone"]'::jsonb, 1, 'FAR is fatalities per 100,000,000 exposed hours, built from the PLL over the crew''s 120000 hours a year, so it counts expected deaths per exposed hours of the group. Deaths per year is the PLL, 0.002420000000. A chance per years is a muddle of a rate and a probability. The hours are the whole crew''s, and one person''s hours give the inflated 121.000000.'),
  ('qra', 'intermediate', 'final', null, 8, 'A colleague asks for the FAR of the JISIKE off-site set, whose expected fatalities are 0.000336000000 per year. What is missing?', '["Nothing, since the engine takes 8760 hours for each person in the town by default", "A whole number of deaths, since a FAR cannot be built on a fractional PLL figure", "A criterion line, since a FAR is read off the F-N curve where it meets the line", "The exposed hours of the people beyond the fence, which the set does not state"]'::jsonb, 3, 'fatalAccidentRateFromPll needs pllPerYr and exposedHoursPerYr, and the engine invents no number, so an off-site FAR waits on the hours someone states for that population. No default of 8760 hours exists; with no hours the call is refused because a rate over no exposure is undefined. A PLL need not be whole. A criterion line belongs to the F-N comparison and plays no part in a FAR.'),
  ('qra', 'intermediate', 'final', null, 9, 'The JISIKE crew PLL stays the same while the crew''s exposed hours double. What happens to the FAR?', '["It doubles, since more hours bring more exposure", "It is unchanged, since the PLL did not move at all", "It halves, since the exposed hours divide the PLL", "It falls by a hundred, the ratio of the two bases"]'::jsonb, 2, 'The model string is FAR = PLL x 100,000,000 / exposed hours per year, so doubling the hours with the PLL fixed halves the rate. More hours would raise the PLL only if the scenarios changed, and here they do not. The FAR depends on the hours as well as the PLL. The base is fixed and plays no part in a change of hours.'),
  ('qra', 'intermediate', 'final', null, 10, 'Which call returns the JISIKE crew FAR?', '["fatalAccidentRateFromPll with pllPerYr 0.002420000000 and exposedHoursPerYr 120000", "fatalAccidentRateFromPll with pllPerYr 0.002420000000 and exposedHoursPerYr 2000", "fatalAccidentRateFromPll with pllPerYr 0.002420000000 and exposedHoursPerYr 8760", "potentialLossOfLife with the four crew scenarios and an exposedHoursPerYr of 120000 added"]'::jsonb, 0, 'The FAR function takes a PLL and the exposed hours of the group, 60 people at 2000 hours each, 120000. Passing 2000 divides by one person and returns 121.000000. 8760 is one person''s whole year, which is no one''s exposure here. potentialLossOfLife takes no hours, so the FAR needs its own call on the PLL it returns.'),
  ('qra', 'intermediate', 'final', null, 11, 'The JISIKE spill with no one near is part of the crew set. What does it do to the crew FAR?', '["It lowers the FAR, since it adds exposure with no death in it", "It raises the FAR, since its frequency is the largest of all", "It makes the FAR undefined, since one scenario has no deaths", "Nothing, since it adds zero to the PLL the FAR is built on"]'::jsonb, 3, 'The spill''s N of 0 gives a contribution of 0.000000000000 to the PLL, and the FAR is the PLL over the exposed hours, which are stated for the crew and do not come from scenarios. So the spill moves the FAR by nothing. Its frequency counts only through N. A zero contribution is ordinary arithmetic, and the one FAR refusal is for no exposed hours.'),
  ('qra', 'intermediate', 'final', null, 12, 'Beside the FAR itself, what does the engine''s FAR result carry?', '["A band that says whether the FAR sits above or below the industry average for the sector", "A basis naming its model string and the safety statistics source of its base", "The PLL split by scenario, so that the FAR can be traced back to each event in turn", "A probability of death per exposed hour for one person on the crew"]'::jsonb, 1, 'Every result carries a basis block, and for the FAR it quotes "FAR = PLL x 100,000,000 / exposed hours per year" and the source RATE_BASES.FAR_100M of the safety statistics engine. The engine bands no FAR against anything. The scenario split is returned by the PLL call. A FAR is a rate over the group''s hours and no probability.'),
  ('qra', 'intermediate', 'final', null, 13, 'Between the flash fire''s 12 deaths and the explosion''s 40, say at 12.5, what does the step read?', '["0.000009700000 per year, equal to F(12)", "0.000000000000 per year, since no N is 12.5", "0.000001700000 per year, equal to F(40)", "0.000008000000 per year, the flash fire alone"]'::jsonb, 2, 'The course reads the step: F(12.5) = F(40) = 0.000001700000 per year, because the next scenarios with 12.5 or more deaths are the explosion at 40 and the toxic cloud at 300. F(12) includes the flash fire, which kills 12, fewer than 12.5. A curve of N or more is not zero between corners. The flash fire alone is the exactly N reading at 12.'),
  ('qra', 'intermediate', 'final', null, 14, 'Under the introduction''s strict wording, what frequency would 300 deaths carry for the off-site set?', '["0.000000000000 per year, since no scenario kills more than 300", "0.000000200000 per year, the toxic cloud sitting at exactly 300 deaths", "0.000001700000 per year, the value at the corner before", "0.000000011111 per year, the Dutch line at that corner"]'::jsonb, 0, 'The course''s comparison prints 0.000000000000 for "more than N" at 300, because the only scenario there has exactly 300 deaths and the strict reading drops it. The engine''s N or more reading keeps it at 0.000000200000. 0.000001700000 is F(40). 0.000000011111 is the criterion at 300, the other side of a comparison.'),
  ('qra', 'intermediate', 'final', null, 15, 'At the JISIKE corner N = 3, what do the scenarios with exactly 3 deaths contribute on their own?', '["0.000049700000", "0.000040000000", "0.000009700000", "0.000010000000"]'::jsonb, 1, 'The two jet fires at the fence, 3e-5 and 1e-5 per year, have exactly 3 deaths each and sum to 0.000040000000, the course''s exactly N column at that corner. 0.000049700000 is F(3), which adds every scenario with more deaths too. 0.000009700000 is what "more than 3" leaves. 0.000010000000 is the second jet fire alone, which leaves out its twin.'),
  ('qra', 'intermediate', 'final', null, 16, 'What frequency sits at the last corner of the JISIKE off-site curve?', '["0.000001500000", "0.000001700000", "0.000000000000", "0.000000200000"]'::jsonb, 3, 'Three hundred deaths are reached by one scenario, the cloud over the town at 2e-7 per year, which the engine writes as 0.000000200000. The explosion on its own, 0.000001500000, has only 40 deaths. Adding the two gives the corner at 40, 0.000001700000. A zero here would mean dropping the only scenario on the corner.'),
  ('qra', 'intermediate', 'final', null, 17, 'How many corners does the JISIKE off-site curve have, and where?', '["Six: one for each off-site scenario", "Five: 0, 3, 12, 40 and 300 deaths", "Four: 3, 12, 40 and 300 deaths", "Three: 12, 40 and 300 deaths only"]'::jsonb, 2, 'Corners sit at each distinct N above zero: the two jet fires share 3, then 12, 40 and 300. Six would count the two jet fires separately and the release that reaches no one. N = 0 is kept out of the curve and its frequency is reported apart. Three corners is the count the Dutch line checks, since 3 is below its range, which is a fact about the comparison.'),
  ('qra', 'intermediate', 'final', null, 18, 'Between two consecutive corners, which corner''s value does the left-continuous step take?', '["The corner to its right, the next larger N", "The corner to its left, the smaller N of the pair", "The average of the two corner values around it", "Zero, since no scenario sits between"]'::jsonb, 0, 'The model string calls the curve a left-continuous step function, and the course reads F(5) as F(12) and F(12.5) as F(40): between corners F takes the value at the next corner up, because every scenario with at least that many deaths lies at or beyond it. The left corner''s value includes scenarios with too few deaths. Nothing averages, and an N or more curve is never zero merely because no scenario sits at that N.'),
  ('qra', 'intermediate', 'final', null, 19, 'Why does the area identity count as a check on the F-N curve?', '["The area is printed in the Purple Book, so matching it reproduces a published worked example of the whole curve", "The area equals the Dutch line''s value at N = 10, so the curve is fixed to the criterion at that point", "The area is the frequency of no deaths, so it confirms that the release reaching no one was left out", "Two separate routes, the area under the steps and the sum of f times N, must land on the same 0.000336000000"]'::jsonb, 3, 'The course sums the area step by step as F at each corner times the width of its step, derived, and gets 0.000336000000, equal to the expected fatalities computed directly; two routes agreeing is a self-consistency check. No published worked F-N example exists. The line at N = 10 is a criterion value unrelated to the area. The frequency of no deaths is 0.000050000000, a different number.'),
  ('qra', 'intermediate', 'final', null, 20, 'Evaluate 1e-3 over N squared at 40 deaths. What frequency results?', '["0.000001700000", "0.000000625000", "0.000006944444", "0.000000011111"]'::jsonb, 1, 'The line is 1e-3 over 40 squared, printed as 0.000000625000 per year. 0.000001700000 is the curve''s F(40), the numerator of the ratio there. 0.000006944444 is the line at N = 12, and 0.000000011111 is the line at N = 300.'),
  ('qra', 'intermediate', 'final', null, 21, 'At the largest JISIKE corner, 300 deaths, how high does the criterion stand?', '["0.000000011111", "0.000000200000", "0.000000625000", "0.000006944444"]'::jsonb, 0, 'At 300 deaths the Dutch constants allow only 0.000000011111 per year. The curve itself stands at 0.000000200000 there, eighteen times higher, which gives the worst ratio of 18.000000. The two other options are the criterion at 40 deaths and at 12 deaths, earlier corners where the allowance is far looser.'),
  ('qra', 'intermediate', 'final', null, 22, 'The explosion and the town cloud hold the curve up at 40 deaths. How many times the Dutch criterion is that?', '["1.396800", "18.000000", "2.720000", "2.000000"]'::jsonb, 2, 'Two scenarios reach 40 deaths, and their combined 0.000001700000 set over the allowance of 0.000000625000 comes to 2.720000. The flash fire corner stands lower at 1.396800, while the town cloud corner stands highest at 18.000000. 2.000000 belongs to a variant whose line stops at 100, where the engine takes its own check.'),
  ('qra', 'intermediate', 'final', null, 23, 'What did Bevi article 13 ask to be done with the three points it printed?', '["Treat them as hard limits, with a permit refused above any one of them", "Use them only for the public, with the workforce under R2P2", "Join them with a slope of minus one to make a societal line of their own", "Compare the group risk with them, calling them an orientation value"]'::jsonb, 3, 'The course says Bevi article 13 asks for the group risk to be COMPARED with the same three points, calling them an orientation value, while the Purple Book caption calls the line a recommended limit for establishments. The course says nothing of permits or a workforce split. The three points lie on a line of slope minus two, alpha 2, and the slope minus one line belongs to the R2P2 discussion.'),
  ('qra', 'intermediate', 'final', null, 24, 'How does the Purple Book Figure 6.8 caption describe the Dutch line?', '["As the one legal limit that replaced Bevi", "As a recommended limit for establishments", "As a point for accidents of fifty or more", "As a line the analyst must derive per plant"]'::jsonb, 1, 'The course says the Figure 6.8 caption prints the line as a recommended limit for establishments. The engine did not read Bevi''s successor, and the caption predates the repeal by decades. Fifty or more is the R2P2 point. The constants are fixed by the source, so no one derives them per plant.'),
  ('qra', 'intermediate', 'final', null, 25, 'Two criterion lines share C. What does a larger alpha do to the line?', '["It falls faster with N, so larger events must be rarer", "It rises with N, so larger events are allowed more often", "It shifts the whole line up by a factor of C at every N", "It leaves the line where it is and only moves its start"]'::jsonb, 0, 'The line is F = C / N^alpha, so a larger alpha makes the allowed frequency fall faster as N grows; the course says 1 is called risk neutral and 2 risk averse. No positive alpha makes the line rise. C scales the line, and alpha shapes it. The start of the line is a separate smallest N, set by its own input.'),
  ('qra', 'intermediate', 'final', null, 26, 'With the Dutch constants capped at N = 100, what ratio does the corner at N = 12 still report?', '["2.000000, since every check is taken again at N = 100 itself", "0.000000, since a capped line skips corners below its top end", "18.000000, since the worst ratio is carried down to each corner", "1.396800, unchanged, since the cap moves only the top of the range"]'::jsonb, 3, 'The course shows the capped comparison as N 12.000000 ratio 1.396800, N 40.000000 ratio 2.720000 and N 100.000000 ratio 2.000000, so the corners inside the range are checked as before. Only the out-of-range corner at 300 is replaced by a check at 100. No corner is skipped, and each corner keeps its own ratio.'),
  ('qra', 'intermediate', 'final', null, 27, 'Why is the worst ratio no longer at the top corner when the Dutch line is capped at N = 100?', '["The cap halves every ratio above N = 40, which leaves the corner at 40 the largest of those checked", "The corner at 12 grows once the cap is set, overtaking every other corner in the checked range", "The corner at 300 is out of range, and F at 100 gives only 2.000000, below the 2.720000 at 40", "The engine reports the first exceeding corner as the worst once any upper end is typed in"]'::jsonb, 2, 'With the cap the engine evaluates F at N = 100, 0.000000200000 against a line of 1e-7, a ratio of 2.000000, and the corner at 40 keeps 2.720000, the largest. The corner at 300 with its ratio of 18.000000 is outside the range. The cap changes no ratio inside the range, and the first exceeding corner, at 12, has the smallest ratio of the three.'),
  ('qra', 'intermediate', 'final', null, 28, 'Which function returns a state against a criterion, the checks at every corner and the worst ratio?', '["fnCurve", "fnCriterionComparison", "potentialLossOfLife", "lsirTransect"]'::jsonb, 1, 'The function table lists fnCriterionComparison as taking scenarios and a criterion and returning the state, the checks at every corner and the worst ratio. fnCurve returns the points, the expected fatalities and the zero-death frequency, with no criterion. potentialLossOfLife returns a PLL. lsirTransect returns individual risk along a line of distances.'),
  ('qra', 'intermediate', 'final', null, 29, 'How does R2P2 paragraph 136 word its one societal point?', '["An accident killing 50 or more in one event is intolerable if more frequent than one in five thousand a year", "An accident killing 50 or more in one event is acceptable if it is less frequent than one in ten thousand a year", "Any accident killing more than 50 people is intolerable at every frequency, with no point to compare it against", "An accident killing 50 or more is intolerable if more frequent than 1e-3 over the square of its N"]'::jsonb, 0, 'The course says an accident killing 50 or more people in one event should be regarded as intolerable if its frequency is more than one in five thousand a year, which the preset holds as N = 50 at 0.000200000000. R2P2 prints no acceptability point at one in ten thousand. A point with no frequency would not be a point. 1e-3 over N squared is the Dutch line.'),
  ('qra', 'intermediate', 'final', null, 30, 'Against the analyst''s line of C = 0.01 and alpha = 1, why is the JISIKE corner at N = 3 checked at all?', '["The engine checks every corner against every line, whatever range is given", "A line of slope minus one is taken to run from N = 3 upward by convention", "The corner at 3 carries two scenarios, and shared corners are always checked", "The line runs from N = 1 by default, so a corner at 3 lies inside its range"]'::jsonb, 3, 'The course says an analyst''s line runs from N = 1 by default, so the corner at 3 is inside it, and it is where the worst ratio of 0.014910 sits. Against the Dutch line, which runs from 10, the same corner is left out, so ranges do matter. No convention starts a line at 3. A shared corner is checked or skipped by its N like any other.'),
  ('qra', 'intermediate', 'final', null, 31, 'For the golden case r2p2-touch, what ratio does the engine compute at N = 50 before the snap places the corner?', '["1.000000000000", "0.9999999999999999", "0.001000", "1.0000001"]'::jsonb, 1, 'F(50) is 1.5e-4 + 5e-5, which is 0.00019999999999999998 in double, against a point of 0.000200000000, a ratio of 0.9999999999999999. The snap then counts it as on the point and the state is TOUCHES. A ratio of exactly 1 is the paper value, which double arithmetic does not reach here. 0.001000 is the JISIKE curve against the point. 1.0000001 is a sum from an event tree the engine refuses.'),
  ('qra', 'intermediate', 'final', null, 32, 'A curve TOUCHES the Dutch line. Has it exceeded the line?', '["Yes: a corner on the line is treated as above it, so touching is a mild exceedance", "Yes, when the touching corner is at the line''s smallest N, where the line is highest", "No: it has no corner strictly above and at least one on the line within the snap", "It depends on the analyst, since the engine leaves a touching curve to be judged"]'::jsonb, 2, 'The course defines TOUCHES as no corner above and at least one on the line within the snap, and EXCEEDS as at least one corner strictly above, so a touching curve has not exceeded. The position of the touching corner makes no difference. The engine returns a definite state word for every comparison and leaves nothing undecided.'),
  ('qra', 'intermediate', 'final', null, 33, 'What problem is the 1e-9 relative snap there to solve?', '["Double arithmetic can land a hair off a value that is exact on paper", "The published lines are printed to three figures and need widening", "Frequencies below 1e-9 per year are too small to be meaningful", "An analyst''s own line is never exact, so every line is blurred"]'::jsonb, 0, 'The golden r2p2-touch sums to 0.00019999999999999998 in double though it is exactly on the point on paper, and without the snap a plain comparison would call it BELOW. The snap is 1e-9 relative, a guard against arithmetic, and has nothing to do with how a source prints its figures. A frequency is not ignored for being small. Every line, preset or supplied, gets the same snap.'),
  ('qra', 'intermediate', 'final', null, 34, 'Which presets does fnCriterionComparison know by name?', '["vrom-establishments, r2p2-para-136 and r2p2-line", "r2p2-workers and r2p2-public, one for each group", "vrom-establishments alone, with R2P2 given by hand", "vrom-establishments and r2p2-para-136"]'::jsonb, 3, 'The refusal for an unknown preset lists exactly two names: one of vrom-establishments, r2p2-para-136, or a line or points the caller gives. r2p2-line is the name the refusal table shows being refused. r2p2-workers and r2p2-public are presets of a different function. The R2P2 point is a preset, so no one has to type it by hand.'),
  ('qra', 'intermediate', 'final', null, 35, 'Which two refusals of fnCriterionComparison name the same field, criterion?', '["A line with no slope, and a line whose smallest N is above its own largest N", "Unknown presets such as ''r2p2-line'' and inherited names such as ''valueOf''", "An unknown preset, and a scenario that has no name of its own at all in the list", "An inherited name, and a curve whose corners all lie below the line"]'::jsonb, 1, 'The refusal table shows both ''r2p2-line'' and ''valueOf'' refused with field criterion and the message beginning criterion: unknown preset, since a name is looked up only among the presets the engine defines. A line with no slope names criterion.exponentAlpha. A nameless scenario is refused by fnCurve on scenarios[0].name. A curve below the line is a result, BELOW, and no refusal.'),
  ('qra', 'intermediate', 'final', null, 36, 'When the engine refuses an input, what number does the refusal carry?', '["The value that was passed, rounded to twelve decimals for the record", "The nearest value the engine would have accepted for that same field", "None of its own: it names the offending field and gives a message", "A result computed with a default in place of the refused input value"]'::jsonb, 2, 'The course says a refusal carries no number of its own, and every function returns either a result with a basis or an object with error and field. The engine suggests no nearest value and computes nothing with a default, since it invents no number. Any number inside a quoted message, such as the 0 in "must be above 0", is part of the engine''s words.'),
  ('qra', 'intermediate', 'final', null, 37, 'Under the Purple Book explosion rules, what happens in a cell at 40000 Pa gauge?', '["Only a fraction of those indoors die, and no one outdoors", "No one dies, since the value is below the lower 10000 Pa gauge threshold", "Only those outdoors die, since buildings shield those inside", "Everyone dies, indoors and outdoors, since it is above 30000 Pa"]'::jsonb, 3, 'Figure 5.5 as the engine applies it: above 30000 Pa gauge everyone dies, above 10000 Pa only a fraction of those indoors, and at or below 10000 Pa no one. At 40000 Pa the top rule holds. The partial indoor rule stops at 30000 Pa. 40000 Pa is far above 10000 Pa. The explosion rules never spare the indoors over the outdoors at the top.'),
  ('qra', 'intermediate', 'final', null, 38, 'A stated peak of exactly 10000 Pa gauge reaches a populated cell. How many there die under the Purple Book rule?', '["No one dies, since 10000 Pa is at or below the lower threshold", "A fraction of those indoors die, since the threshold is reached", "Everyone outdoors dies, since the indoors rule starts only above it", "Everyone dies, since any value on a printed edge takes the upper rule"]'::jsonb, 0, 'The course''s rows show zero at 5000 and at 10000 Pa gauge, and says a value at a threshold falls in the lower rule. Only above 10000 Pa do some of those indoors die. No rule kills those outdoors below 30000 Pa. An edge value always takes the rule below it, which is the same convention as exactly 30000 Pa.'),
  ('qra', 'intermediate', 'final', null, 39, 'From which Purple Book table do the day and night fractions of people indoors come?', '["Table 4.5", "Table 4.7", "Table 5.3", "Figure 6.8"]'::jsonb, 2, 'The course cites Table 5.3 for the fractions of the population indoors by period, and the refusal for an unknown period names it too. Table 4.5 is the direct ignition probability table and Table 4.7 classifies reactivity, both Associate lookups. Figure 6.8 is the Dutch line.'),
  ('qra', 'intermediate', 'final', null, 40, 'For the same stated toxic PE, why does the night case give a smaller Fd than the day case?', '["The engine lowers PE itself at night, since fewer people are awake and outside then", "More people are indoors at night, where the rule gives a smaller fraction dying", "Night is refused unless a fraction indoors is given, and that fraction sets Fd lower", "The toxic rule applies only to people outdoors, who are fewer by night"]'::jsonb, 1, 'The course''s toxic rows share PE 0.4 and FE,in 0.040000, and only the fraction indoors changes, 0.93 by day and 0.99 by night, so more weight falls on the smaller indoor fraction. PE is a stated input from the consequence course, and the engine never alters it. A period of night is accepted as it stands. The rule counts deaths indoors as well as outdoors. These figures teach the rule and are graded nowhere.'),
  ('qra', 'intermediate', 'final', null, 41, 'What must pbFatalityFractions be given for a toxic cloud?', '["A concentration and an exposure time, from which it builds the probability itself", "The number of people in the cell, since it returns the expected deaths directly", "Both a period and a fraction of people indoors, so that the two can be checked", "A stated probability of death, and either a period or a fraction of people indoors"]'::jsonb, 3, 'The function table lists the effect and its input, and a period or a fraction indoors; for a toxic cloud the input is the probability of death, which is a stated input from the consequence course, and the engine refuses a toxic call without it. A concentration and an exposure time are consequence modelling, which belongs to the consequence course. The call returns fractions, and the expected deaths in a cell are Fd times its people. A period and a fraction together are refused.'),
  ('qra', 'intermediate', 'final', null, 42, 'In the JISIKE off-site results, which figure is a frequency of events and which an expected number of deaths?', '["F(3), 0.000049700000, is a frequency; 0.000336000000 is expected deaths per year", "F(3), 0.000049700000, is expected deaths; 0.000336000000 is a frequency of events", "Both are frequencies of events, one counted from N = 3 and one counted from N = 0", "Both are expected deaths per year, the first taken at one corner and the second overall"]'::jsonb, 0, 'F(3) is the frequency per year of events with 3 or more deaths, a corner of the curve. 0.000336000000 is the sum of f times N, expected fatalities per year, equal to the area under the curve. Swapping them, or calling both by one name, loses the distinction the Professional tier rests on: the curve says how often, and the sum says how many on average.');
